/**
 * Common fields shared across all retry policy configurations
 */
type RetryPolicyBase = {
    /** Display name shown in the retry policy list. */
    name?: string

    /**
     * Fields evaluated in the condition to determine whether to retry.
     * @default `['http_method', 'status_code', 'error', 'response_body', 'response_headers']`
     * @example ['status_code', 'error']
     */
    restrictTo?: string[]
}

/**
 * Common fields for fixed_time_interval and exponential_backoff strategies
 */
type FixedOrExponentialBase = {
    /**
     * Retry strategy to use.
     * - `'fixed_time_interval'`: Wait a fixed amount of time between retries.
     * - `'exponential_backoff'`: Wait an exponentially increasing amount of time between retries.
     * @default `'fixed_time_interval'`
     */
    retryStrategy?: 'fixed_time_interval' | 'exponential_backoff'

    /** Maximum number of retry attempts before the request is considered failed. */
    count?: number

    /** Wait interval between retries in seconds. */
    interval?: number
}

/**
 * Retry policy using the retry_after strategy.
 * - Must use `connectionType: 'http_retry_conditions'`
 * - Requires `maxElapsedTime`
 * - Cannot use `count` or `interval`
 * - Can optionally specify `condition`
 */
type RetryAfter = RetryPolicyBase & {
    /**
     * Retry strategy to use.
     * - `'retry_after'`: Use the `Retry-After` header from the response.
     */
    retryStrategy: 'retry_after'
    /**
     * Connection type for the retry policy.
     * - `'http_retry_conditions'`: HTTP connection type.
     */
    connectionType?: 'http_retry_conditions'

    /**
     * Maximum total time budget for all retry attempts in seconds.
     * **Required** when `retryStrategy` is `'retry_after'`.
     * Must not exceed 86400 (24 hours), as enforced by the
     * `glide.fdih.retry.max_time_in_seconds` system property.
     */
    maxElapsedTime: number

    /**
     * Encoded query condition used to determine whether to retry after a failed attempt.
     * Uses ServiceNow encoded query syntax with operators like ^OR (OR), BETWEEN (range), IN (list).
     * @see https://docs.servicenow.com/bundle/xanadu-platform-administration/page/administer/reference-pages/concept/c_EncodedQueryStrings.html
     * @example 'status_codeIN429,500,502,503,504' // Retry on specific status codes
     * @example 'status_code=429^ORstatus_codeBETWEEN500@599' // Retry on 429 or 5xx errors
     */
    condition?: string
}

/**
 * Retry policy using fixed_time_interval or exponential_backoff strategy with HTTP connection type.
 * - Can use `count` and `interval`
 * - Cannot use `maxElapsedTime`
 * - Can optionally specify `condition` (HTTP-only)
 */
type HttpRetry = RetryPolicyBase &
    FixedOrExponentialBase & {
        /**
         * Connection type for the retry policy.
         * - `'http_retry_conditions'`: HTTP connection type.
         */
        connectionType?: 'http_retry_conditions'

        /**
         * Encoded query condition used to determine whether to retry after a failed attempt.
         * Only valid when `connectionType` is `'http_retry_conditions'`.
         * Uses ServiceNow encoded query syntax with operators like ^OR (OR), BETWEEN (range), IN (list).
         * @see https://docs.servicenow.com/bundle/xanadu-platform-administration/page/administer/reference-pages/concept/c_EncodedQueryStrings.html
         * @example 'status_codeIN429,500,502,503,504' // Retry on specific status codes
         * @example 'status_code=429^ORstatus_codeBETWEEN500@599' // Retry on 429 or 5xx errors
         */
        condition?: string
    }

/**
 * Retry policy using fixed_time_interval or exponential_backoff strategy with JDBC or SFTP connection type.
 * - Can use `count` and `interval`
 * - Cannot use `maxElapsedTime`
 * - Cannot use `condition` (HTTP-only feature)
 */
type NonHttpRetry = RetryPolicyBase &
    FixedOrExponentialBase & {
        /**
         * Connection type for the retry policy.
         * - `'jdbc_retry_conditions'`: JDBC connection type.
         * - `'basic_retry_conditions'`: SFTP connection type.
         */
        connectionType: 'jdbc_retry_conditions' | 'basic_retry_conditions'
    }

/**
 * @interface
 * Defines a retry policy for outbound integration connections.
 *
 * A retry policy specifies how many times to retry a failed connection,
 * how long to wait between attempts, and under what conditions retries apply.
 * Supports HTTP, JDBC, and SFTP connection types.
 *
 * The type uses a discriminated union to enforce constraints at compile-time:
 * - `retry_after` strategy requires `maxElapsedTime` and HTTP connection type
 * - `condition` field is only valid for HTTP connection types
 * - `count` and `interval` are not valid with `retry_after` strategy
 */
export type RetryPolicy = Now.Internal.WithIdAndMetadata<RetryAfter | HttpRetry | NonHttpRetry>

export function RetryPolicy(config: RetryPolicy) {
    return config
}
